function useQuery(url:string|null): {data?:Row,error?:string}{
 const [state,set]=useState<{url:string,data?:Row,error?:string}>();
 useEffect(()=>{if(!url)return;const c=new AbortController();publicGetJson<Row>(url,c.signal).then(data=>set({url,data})).catch(e=>{if(!c.signal.aborted)set({url,error:e.message});});return()=>c.abort();},[url]);
 return state?.url===url?state:{};
}
