export function ResearchWorkbench(){
 const {t}=useUiLocale();
 const [search,setSearch]=useState(location.search);const params=new URLSearchParams(search);const mode=params.get('view')||'selection';
 const visitedQueries=useRef(new Map<string,string>());
 const focusDispositionResults=useRef(false);
 const context=useQuery('/api/workbench/context');const [notice,setNotice]=useState('');const [busy,setBusy]=useState(false);const [builderQuery,setBuilderQuery]=useState('');const builders=useQuery(builderQuery?'/api/research/actors?q='+enc(builderQuery):null);
 useEffect(()=>{const sync=()=>setSearch(location.search);window.addEventListener('popstate',sync);return()=>window.removeEventListener('popstate',sync);},[]);
 function go(p:Row,reset=false){const n=fillMissingWorkbenchPins(rememberedWorkbenchQuery(new URLSearchParams(search),p,visitedQueries.current,reset),{snapshot:context.data?.publicCoreSha256||result.data?.publicCoreSha256,assessment:context.data?.occurrenceAssessmentSha256});const next=PATH+'?'+n.toString();history.pushState({},'',next);setSearch(location.search);setNotice('');}
 const section=params.get('section')||'events';const api=workbenchRequestQuery(params,mode);
 const sequenceNeedsActors=mode==='selection'&&section==='sequences'&&(!params.get('actor')||!params.get('other'));
 const unsupportedNameQuery=(mode==='identities'||mode==='occurrences')&&params.has('q');
 let url:string|null=null;
 if(mode==='selection'&&!sequenceNeedsActors&&(params.get('actor')||params.get('organ')||params.get('source')||params.get('q')))url='/api/workbench/selection?'+api;
 if(mode==='compare'&&params.get('left')&&params.get('right'))url='/api/workbench/compare?'+api;
 if((mode==='timeline'||mode==='claims')&&params.get('organ'))url='/api/workbench/'+mode+'/'+enc(params.get('organ')!)+'?'+api;
 if(mode==='terms')url='/api/workbench/terms?'+api;
 if(mode==='occurrences')url='/api/workbench/occurrences?'+api;
 if(mode==='identities')url='/api/workbench/identities?'+api;
 if(mode==='organs'&&params.get('organs'))url='/api/workbench/organ-comparison?'+api;
 const dispositionRequested=mode==='dispositions'&&(params.has('stop')||params.has('scope'));
 if(dispositionRequested&&params.has('snapshot'))url='/api/workbench/dispositions?'+api;
 const result=useQuery(url);const data=result.data;const facets=context.data?.facets;
 const disposition=mode==='dispositions'&&data?data as DispositionResult:undefined;
 const packageApi=new URLSearchParams(api);packageApi.set('format','ro-crate');
 const packagePath=mode==='dispositions'?undefined:['selection','terms','occurrences'].includes(mode)?'/api/workbench/'+mode+'/export':url?.split('?')[0];
 useEffect(()=>{document.title=t('workbench.pageTitle','Organological research workbench | MODAVIS Navigator','Recherchewerkzeuge für Orgelkunde | MODAVIS Navigator');},[t]);
 useEffect(()=>{if(!context.data)return;const current=new URLSearchParams(search);const n=fillMissingWorkbenchPins(current,{snapshot:context.data.publicCoreSha256,assessment:context.data.occurrenceAssessmentSha256,...(mode==='compare'&&data?.left&&data?.right?{leftRevision:data.left.metadata.description_revision,rightRevision:data.right.metadata.description_revision}:{})});if(n.toString()!==current.toString()){history.replaceState({},'',PATH+'?'+n);setSearch(location.search);}},[context.data,data,mode,search]);
 const snapshotMismatch=!!(params.get('snapshot')&&context.data&&params.get('snapshot')!==context.data.publicCoreSha256);
 const dispositionPinned=disposition&&!snapshotMismatch&&params.getAll('snapshot').length===1&&params.get('snapshot')===disposition.publicCoreSha256;
 useEffect(()=>{
  if(mode!=='dispositions'||result.error||snapshotMismatch){focusDispositionResults.current=false;return;}
  if(!disposition||!focusDispositionResults.current)return;
  focusDispositionResults.current=false;
  document.getElementById('wb-results')?.focus();
 },[disposition,mode,result.error,snapshotMismatch]);
 function submit(e:React.FormEvent<HTMLFormElement>){e.preventDefault();const values=Object.fromEntries(new FormData(e.currentTarget).entries());go({...values,view:mode,page:0},true);}
 function selectAccount(id:string,revision:string){const existing=params.get('left');if(!existing)go({left:id,leftRevision:revision});else if(existing===id)go({left:null,leftRevision:null});else go({right:id,rightRevision:revision,view:'compare'});}
 async function download(format:string){setBusy(true);setNotice('');try{const r=await fetch('/api/workbench/selection/export?'+api+'&format='+format);if(!r.ok){const d=await r.json();throw new Error(d.error);}const blob=await r.blob();const u=URL.createObjectURL(blob);const a=document.createElement('a');a.href=u;a.download='modavis-research.'+format;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);setNotice(t('workbench.download.success','Complete filtered selection downloaded.','Die vollständige gefilterte Auswahl wurde heruntergeladen.'));}catch(e){setNotice(String(e));}finally{setBusy(false);}}
 const views=WORKBENCH_VIEWS.map(view=>{
  const id=view.id==='dispositions'?'disposition.view':`workbench.view.${view.id}`;
  return {...view,label:t(`${id}.label`,view.label,view.de.label),title:t(`${id}.title`,view.title,view.de.title),description:t(`${id}.description`,view.description,view.de.description)};
 });
 const currentView=views.find(view=>view.id===mode);
 return <section className="research-workbench story-page" aria-label={t('workbench.region','Organological research workbench','Recherchewerkzeuge für Orgelkunde')}>
 <div className="wb-breadcrumbs"><a href="/use-cases">{t('workbench.breadcrumb.research','Research questions','Forschungsfragen')}</a><span aria-hidden="true">/</span><span>{t('workbench.breadcrumb.current','Workbench','Recherchewerkzeuge')}</span></div>
 <header className="story-hero wb-hero"><div><p className="eyebrow">{t('workbench.eyebrow','Organological research','Orgelkundliche Forschung')}</p><h1>{t('workbench.heading','Research workbench','Recherchewerkzeuge')}</h1><p>{t('workbench.lead','Follow the evidence. Keep the source in view.','Verfolgen Sie die Belege bis zu den zugehörigen Quellen.')}</p></div><button className="wb-workspace-action" onClick={()=>window.dispatchEvent(new CustomEvent('modavis:workspace-open'))}><FolderOpen size={17} aria-hidden="true"/>{t('workbench.workspace.open','Open workspace','Recherche-Arbeitsbereich öffnen')}</button></header>
 <WorkbenchViews mode={mode} go={go} views={views}/>
 <div className="wb-view-heading"><h2>{currentView?.title||t('workbench.view.fallback','Research view','Forschungsansicht')}</h2><p>{currentView?.description||t('workbench.view.choose','Choose a research view to continue.','Wählen Sie eine Forschungsansicht aus.')}</p>{!snapshotMismatch&&(mode==='dispositions'?disposition&&<a className="wb-result-jump" href="#wb-results">{t('disposition.view.goToResults','Go to results','Zu den Ergebnissen')} <span aria-hidden="true">↓</span></a>:<ResultJump data={data}/>)}</div>
 {context.error&&<p role="alert">{context.error}</p>}{snapshotMismatch&&<p role="alert">{t('workbench.error.snapshot','This link belongs to a different data snapshot. Its results cannot be reproduced against this candidate.','Dieser Link gehört zu einem anderen Datenstand. Mit dem aktuellen Datenstand lassen sich die Ergebnisse nicht reproduzieren.')}</p>}
 {sequenceNeedsActors&&<p role="status">{t('workbench.sequences.chooseActors','Enter the identifiers of the earlier and later actors to compare their documented work.','Geben Sie die Kennungen zu den früheren und späteren Ereignissen ein, um die dokumentierten Arbeiten zu vergleichen.')}</p>}
 <details className="wb-help wb-starters"><summary>{t("workbench.starter.title","Start with an example research question","Mit einer beispielhaften Forschungsfrage beginnen")}</summary><div className="wb-templates"><button onClick={()=>go({view:'selection',actor:'W8AZ-2EJP-P',section:'events'},true)}>{t("workbench.starter.moeller","Möller: documented interventions","Dokumentierte Eingriffe von Möller")}</button><button onClick={()=>go({view:'selection',organ:'EAXV-HAAS-S',section:'configurations'},true)}>{t("workbench.starter.enschede","Enschede: compare configuration accounts","Dispositionsbeschreibungen aus Enschede vergleichen")}</button><button onClick={()=>go({view:'timeline',organ:'031M-S34V-V'},true)}>{t("workbench.starter.pels","Pels: construction, transfer and restoration","Neubau, Versetzung und Restaurierung bei Pels")}</button><button onClick={()=>go({view:'terms',mode:'stops',q:'Principal'},true)}>{t("workbench.starter.principal","Principal: wording and source distributions","Schreibweisen und Quellen zum Register Principal")}</button><button onClick={()=>go({view:'claims',organ:'FFH7-Z9KV-V'},true)}>{t("workbench.starter.frauenthal","Frauenthal: separately attributed claims","Quellenaussagen zur Orgel in Frauenthal")}</button><button onClick={()=>go({view:'identities'},true)}>{t("workbench.starter.identities","People, workshops and generations","Personen, Werkstätten und Generationen")}</button><button type="button" onClick={()=>go({view:'dispositions',scope:'account',stop:['Principal|8','Octave|4'],page:0},true)}>{t('disposition.view.example','Principal 8′ and Octave 4′ in one account','Principal 8′ und Octave 4′ in einer Dispositionsbeschreibung')}</button></div></details>
 {(mode==='selection')&&<details className="wb-builder-search"><summary>{t("workbench.builder.find","Find an actor identifier by name","Kennung einer Person oder Organisation nach Namen suchen")}</summary><label>{t("workbench.builder.name","Builder name","Name des Orgelbauers oder der Werkstatt")}<input value={builderQuery} onChange={e=>setBuilderQuery(e.target.value)} placeholder="Möller, Schuke…"/></label>{builders.error&&<p role="alert">{builders.error}</p>}<div className="wb-builder-results">{builders.data?.items?.map((x:Row)=><button key={x.id} onClick={()=>go({actor:x.id,section:'events',page:0})}>{t("workbench.builder.organs","{label} · {count, number} organs","{label} · {count, number} Orgeln",{label:x.label,count:x.organ_count})}</button>)}</div></details>}
 {!['identities','occurrences','dispositions'].includes(mode)&&<ResearchFilters key={mode+':'+api.toString()} params={params} mode={mode} facets={facets} onSubmit={submit}/>}
 {mode==='dispositions'&&<DispositionForm params={params} onSearch={(stop,scope)=>go({view:mode,stop,scope,page:0},true)}/>}
 {mode==='occurrences'&&<OccurrenceFilters params={params} data={data} go={go}/>}
 <AppliedFilters params={params} mode={mode} go={go}/>
 {mode!=='dispositions'&&<details className="wb-context"><summary>{t("workbench.context.heading","How to read this evidence","Hinweise zur Einordnung der Belege")}</summary><p>{mode==='occurrences'?t("workbench.context.attributions","Inspect source-attributed mentions and their bounded identity assessments. Unassessed mentions remain unassessed.","Prüfen Sie Quellennennungen und die zugehörigen Identitätsbewertungen. Bei unbewerteten Nennungen bleibt die Zuordnung offen."):mode==='terms'?t("workbench.context.terms","Counts refer to recorded wording and captured source coverage. Country describes the source’s current listing location.","Die Zahlen beziehen sich auf den überlieferten Wortlaut und die erfassten Quellen. Das Land bezeichnet den im Quelleneintrag genannten aktuellen Standort."):mode==='compare'?t("workbench.context.compare","Compare two separately identified accounts at their exact retained revisions.","Vergleichen Sie zwei einzeln gekennzeichnete Beschreibungen in ihren jeweils erhaltenen Fassungen."):mode==='organs'?t("workbench.context.organs","Compare two to four documented organ records, then inspect their source accounts.","Vergleichen Sie zwei bis vier dokumentierte Orgeldatensätze und prüfen Sie die zugehörigen Quellenbeschreibungen."):mode==='selection'&&section==='organs'?t("workbench.context.organSelection","Each result is an existing public organ record with retained source membership.","Jeder Treffer ist ein bestehender öffentlicher Orgeldatensatz mit erhaltenen Quellenzuordnungen."):mode==='selection'&&section==='configurations'?t("workbench.context.accountSelection","Each result is a separately dated or qualified source account. Capture dates do not establish an instrument’s configuration date.","Jeder Treffer ist eine eigenständig datierte oder zeitlich eingeordnete Quellenbeschreibung. Das Erfassungsdatum lässt offen, wann der beschriebene Orgelzustand bestand."):t("workbench.context.fallback","Retain the source, date qualification and evidence alongside each historical assertion.","Bewahren Sie zu jeder historischen Aussage die Quelle, die Datierungshinweise und die Belege auf.")}</p>{data?.method&&mode!=='organs'&&<p>{data.method}</p>}{data?.identityFilterMethod&&mode==='selection'&&['events','sequences'].includes(section)&&params.get('actor')&&<p>{data.identityFilterMethod}</p>}</details>}
 {mode==='dispositions'?dispositionPinned&&<DispositionActions key={api.toString()} data={disposition} params={params} exportLimit={context.data?.exportLimit}/>:<div className="wb-selection-actions"><div><button className="wb-link-action" onClick={async()=>{try{await navigator.clipboard.writeText(location.href);setNotice(t("workbench.actions.copied","Research link copied.","Forschungslink kopiert."));}catch{setNotice(t("workbench.actions.copyFallback","Copy the address from your browser to retain this selection.","Kopieren Sie die Adresse aus Ihrem Browser, um diese Auswahl festzuhalten."));}}}><LinkIcon size={15} aria-hidden="true"/>{t("workbench.actions.copy","Copy research link","Forschungslink kopieren")}</button><a href={PATH+search}>{t("workbench.actions.pinned","Pinned selection URL","Link zur gebundenen Auswahl")}</a></div>{mode==='selection'&&data&&<details className="wb-downloads"><summary>{t("workbench.actions.download","Download selection","Auswahl herunterladen")}</summary><div><button disabled={busy} onClick={()=>download('json')}>{t("workbench.actions.json","Complete selection · JSON","Vollständige Auswahl · JSON")}</button><button disabled={busy} onClick={()=>download('csv')}>{t("workbench.actions.csv","Complete selection · CSV","Vollständige Auswahl · CSV")}</button></div></details>}</div>}{notice&&<p className="wb-feedback" role="status">{notice}</p>}
 {result.error&&<div className="wb-error" role="alert">
  <strong>{mode==='dispositions'?t('disposition.error.load','The disposition search could not be loaded','Die Dispositionssuche konnte nicht geladen werden'):t("workbench.error.load","This selection could not be loaded","Diese Auswahl konnte nicht geladen werden")}</strong>
  <p>{result.error}</p>
  {unsupportedNameQuery ? <>
   <p>{t('workbench.error.nameQuery','Name searches are available in the people directory. You can also remove the name search and keep this research snapshot.','Die Namenssuche ist im Personenverzeichnis verfügbar. Sie können die Namenssuche auch entfernen und den Datenstand beibehalten.')}</p>
   <div className="wb-tools">
    <button type="button" onClick={()=>go({q:null,page:0})}>{t('workbench.error.removeNameQuery','Remove the name search','Namenssuche entfernen')}</button>
    {params.getAll('q').length===1&&params.get('q')&&<a href={'/persons?'+new URLSearchParams({q:params.get('q')!,publication_state:'all'})}>{t('workbench.error.searchNames','Search the people directory','Personenverzeichnis durchsuchen')}</a>}
   </div>
  </> : <a href={PATH+search}>{mode==='dispositions'?t('disposition.error.retry','Retry the pinned search','Gebundene Suche erneut ausführen'):t("workbench.error.retry","Retry the pinned selection","Gebundene Auswahl erneut aufrufen")}</a>}
 </div>}
 {(url||dispositionRequested&&!context.error)&&!data&&!result.error&&<div className="wb-loading" role="status"><span aria-hidden="true"/><div>{mode==='dispositions'?<strong>{t('disposition.loading','Searching captured stop rows…','Erfasste Registereinträge werden durchsucht …')}</strong>:<><strong>{t("workbench.loading.title","Loading research evidence…","Forschungsbelege werden geladen …")}</strong><p>{t("workbench.loading.help","Your selected filters and snapshot stay attached.","Ihre Filter und der ausgewählte Datenstand bleiben erhalten.")}</p></>}</div></div>}
 {!url&&mode==='organs'&&<div className="wb-empty"><h2>{t("workbench.organs.compare","Compare documented instruments","Dokumentierte Instrumente vergleichen")}</h2><p>{t("workbench.organs.empty","Keep two to four organ records in your research workspace, then open a common-snapshot comparison.","Speichern Sie zwei bis vier Orgeldatensätze in Ihrem Recherche-Arbeitsbereich und öffnen Sie den Vergleich auf Grundlage desselben Datenstands.")}</p><button onClick={()=>window.dispatchEvent(new CustomEvent('modavis:workspace-open'))}>{t("workbench.organs.choose","Choose retained organs","Gespeicherte Orgeln auswählen")}</button></div>}
 {!url&&mode==='compare'&&<div className="wb-empty"><span className="wb-kicker">{t("workbench.accounts.kicker","Two accounts · exact revisions","Zwei Beschreibungen · festgelegte Fassungen")}</span><h2>{t("workbench.accounts.choose","Choose the accounts to compare","Beschreibungen für den Vergleich auswählen")}</h2><p>{t("workbench.accounts.empty","Select a first and second account from configuration results, or open a pair saved in your workspace.","Wählen Sie zwei Beschreibungen aus den Suchergebnissen oder öffnen Sie ein gespeichertes Paar aus Ihrem Recherche-Arbeitsbereich.")}</p><button className="wb-primary" onClick={()=>go({view:'selection',section:'configurations'})}>{t("workbench.accounts.find","Find configuration accounts","Dispositionsbeschreibungen suchen")}<ArrowRight size={16} aria-hidden="true"/></button></div>}
 {!url&&mode==='selection'&&<div className="wb-empty"><h2>{t("workbench.selection.empty","Your research starts here","Hier beginnt Ihre Recherche")}</h2><p>{t("workbench.selection.emptyHelp","Choose a research question above, find a builder, or enter an organ name to bring the evidence into view.","Wählen Sie oben eine Forschungsfrage, suchen Sie einen Orgelbauer oder geben Sie den Namen einer Orgel ein.")}</p></div>}
 {data&&!snapshotMismatch&&<section id="wb-results" className="wb-results-region" tabIndex={-1} aria-label={mode==='dispositions'?t('disposition.result.region','Disposition search results','Ergebnisse der Dispositionssuche'):t("workbench.results.region","Research results","Forschungsergebnisse")}>
 {packagePath&&context.data?.researchPackageAvailable&&<p><a href={packagePath+'?'+packageApi} download="modavis-research-selection.zip">{t("workbench.download.package","Download complete research package · RO-Crate ZIP","Vollständiges Forschungspaket herunterladen · RO-Crate ZIP")}</a></p>}
 {disposition&&<DispositionResults data={disposition} page={Number(params.get('page')||0)} onPage={page=>{focusDispositionResults.current=true;go({page});}}/>}
 {mode==='organs'&&<OrganComparison data={data}/>}
 {mode==='occurrences'&&<><Pager data={data} go={go} page={Number(params.get('page')||0)}/><OccurrenceResults data={data}/><Pager data={data} go={go} page={Number(params.get('page')||0)}/><a href={'/api/workbench/occurrences/export?'+api} download="modavis-identity-occurrences.json">{t("workbench.occurrences.download","Download complete attribution selection · JSON","Vollständige Auswahl der Zuschreibungen herunterladen · JSON")}</a></>}

 {mode==='selection'&&<>{data.items.length===0&&<div className="wb-empty wb-no-results"><h2>{t("workbench.selection.noResults","No records match this selection","Keine Datensätze entsprechen dieser Auswahl")}</h2><p>{t("workbench.selection.refine","Adjust a source or date filter, or try a different organ name. Your current filters are shown above.","Ändern Sie den Quellen- oder Datumsfilter oder suchen Sie nach einem anderen Orgelnamen. Ihre aktuellen Filter stehen oben.")}</p></div>}{data.identityAssessments?.length>0&&<details open><summary>{t("workbench.selection.identity","Identity evidence affects this selection","Belege zur Identität beeinflussen diese Auswahl")}</summary>{data.identityAssessments.map((g:Row)=><p key={g.nativeId}><strong>{g.sourceNames.join(' / ')}:</strong> {g.remaining}</p>)}<button onClick={()=>go({view:'identities'})}>{t("workbench.selection.primary","Inspect the identity research and primary sources","Identitätsrecherche und Primärquellen prüfen")}</button></details>}<Pager data={data} go={go} page={Number(params.get('page')||0)}/>{params.get('left')&&<div className="wb-selection-tray" role="status"><Bookmark size={18} aria-hidden="true"/><div><strong>{params.get('right')?t("workbench.selection.twoSelected","Two accounts selected","Zwei Beschreibungen ausgewählt"):t("workbench.selection.firstSelected","First account selected","Erste Beschreibung ausgewählt")}</strong><p>{params.get('right')?t("workbench.selection.retainsRevisions","Your comparison retains both account revisions.","Der Vergleich hält beide Beschreibungsfassungen fest."):t("workbench.selection.chooseSecond","Choose a second account to compare.","Wählen Sie eine zweite Beschreibung zum Vergleich.")} <code>{params.get('left')}</code></p></div>{params.get('right')&&<button onClick={()=>go({view:'compare'})}>{t("workbench.selection.compare","Open comparison","Vergleich öffnen")}<ArrowRight size={15} aria-hidden="true"/></button>}</div>}<div className="wb-results">{data.items.map((x:Row,i:number)=><article key={x.id+':'+i}><h2><a href={x.organHref}>{x.label}</a></h2>{section==='events'?<Event value={x.evidence}/>:section==='sequences'?<div className="wb-columns"><Event value={x.evidence}/><Event value={x.later}/></div>:section==='configurations'?<AccountSummary value={{...x.evidence,href:x.href}} actions={<button className="wb-compare-action" onClick={()=>selectAccount(x.id,x.evidence.description_revision)}>{params.get('left')===x.id?t("workbench.selection.removeFirst","Remove first account","Erste Beschreibung entfernen"):t("workbench.selection.selectComparison","Select for comparison","Für den Vergleich auswählen")}</button>}/>:<><p>{t("workbench.selection.sourceCount","{count, number} source records. Independent confirmation is unestablished.","{count, number} Quellendatensätze. Die unabhängige Bestätigung ist ungeklärt.",{count:x.sources.length})}</p><Evidence value={x.sources}/></>}{['events','sequences'].includes(section)&&<AttributionNotes items={[...(x.identityOccurrences||[]),...(x.laterIdentityOccurrences||[])]} inspect={v=>go(v,true)}/>}<div className="wb-tools"><button onClick={()=>go({view:'timeline',organ:x.organ},true)}>{t("workbench.selection.timeline","Read qualified timeline","Chronologie mit Datierungsangaben öffnen")}</button><button onClick={()=>go({view:'claims',organ:x.organ},true)}>{t("workbench.selection.claims","Compare source claims","Quellenaussagen vergleichen")}</button><button onClick={()=>go({view:'selection',section:'configurations',organ:x.organ},true)}>{t("workbench.selection.configurations","Inspect configuration accounts","Dispositionsbeschreibungen prüfen")}</button></div></article>)}</div><details><summary>{t("workbench.selection.identityDetails","Citation and selection identity","Zitierangaben und Kennung der Auswahl")}</summary><p>{t("workbench.selection.cite","MODAVIS Navigator research selection {selection} · core {core} · filters {filters}. The release and the checksum identify this preparation. Publication status is recorded separately.","Forschungsauswahl in MODAVIS Navigator {selection} · Kerndaten {core} · Filter {filters}. Version und Prüfsumme identifizieren diesen Datenstand. Der Veröffentlichungsstatus wird getrennt angegeben.",{selection:data.selectionSha256,core:data.publicCoreSha256,filters:JSON.stringify(data.filters)})}</p></details></>}
 {mode==='compare'&&<><div className="wb-columns">{['left','right'].map(side=><article key={side}><h2>{side==='left'?t("workbench.compare.first","First account","Erste Beschreibung"):t("workbench.compare.second","Second account","Zweite Beschreibung")}</h2><AccountSummary value={{...data[side].metadata,href:data[side].href}}/><p className="wb-revision">{t("workbench.compare.revision","Retained revision","Erhaltene Fassung")} <code>{data[side].metadata.description_revision}</code></p></article>)}</div><details className="wb-method"><summary>{t("workbench.compare.method","How entries are compared","Wie die Einträge verglichen werden")}</summary><p>{data.comparison.method}</p></details><div className="wb-stats"><span>{t("workbench.compare.pairs","{count, number} matching entry pairs","{count, number} übereinstimmende Eintragspaare",{count:data.comparison.both.length})}</span><span>{t("workbench.compare.leftOnly","{count, number} only in first account","{count, number} nur in der ersten Beschreibung",{count:data.comparison.leftOnly.length})}</span><span>{t("workbench.compare.rightOnly","{count, number} only in second account","{count, number} nur in der zweiten Beschreibung",{count:data.comparison.rightOnly.length})}</span><span>{t("workbench.compare.ambiguous","{count, number} ambiguous groups","{count, number} Gruppen mit mehrdeutiger Zuordnung",{count:data.comparison.ambiguous.length})}</span></div><details open><summary>{t("workbench.compare.matches","Matching recorded entries","Übereinstimmende erfasste Einträge")}</summary><ul>{data.comparison.both.map((x:Row,i:number)=><li key={i}><Stop entry={x.left}/> ↔ <Stop entry={x.right}/></li>)}</ul></details><div className="wb-columns">{['leftOnly','rightOnly'].map((key,i)=><details key={key} open><summary>{i===0?t("workbench.compare.onlyFirst","Only documented in first account","Nur in der ersten Beschreibung belegt"):t("workbench.compare.onlySecond","Only documented in second account","Nur in der zweiten Beschreibung belegt")}</summary><ul>{data.comparison[key].map((x:Row,j:number)=><li key={j}><Stop entry={x}/></li>)}</ul></details>)}</div><details><summary>{t("workbench.compare.uncertain","Uncertain correspondences","Unsichere Entsprechungen")}</summary>{data.comparison.ambiguous.map((x:Row,i:number)=><div key={i}><p>{x.reason}</p><Evidence value={x}/></div>)}</details><a href={'/api/workbench/compare?'+api} download="modavis-account-comparison.json">{t("workbench.compare.download","Download comparison evidence","Belege zum Vergleich herunterladen")}</a></>}
 {mode==='timeline'&&<><h2>{t("workbench.timeline.heading","Documented events and qualified accounts","Dokumentierte Ereignisse und datierte Beschreibungen")}</h2><div className="wb-columns"><section><h3>{workbenchResultCount(data.events.length,'event assertions',t)}</h3>{data.events.map((x:Row)=><Event key={x.event_id} value={x}/>)}</section><section><h3>{workbenchResultCount(data.accounts.length,'configuration accounts',t)}</h3>{data.accounts.map((x:Row)=><article key={x.description_id}><AccountSummary value={x}/><button onClick={()=>go({view:'selection',section:'configurations',organ:data.organId},true)}>{t("workbench.timeline.compare","Compare this organ’s accounts","Beschreibungen dieser Orgel vergleichen")}</button></article>)}</section></div><a href={url||''} download="modavis-timeline.json">{t("workbench.timeline.download","Download timeline evidence","Belege zur Chronologie herunterladen")}</a></>}
 {mode==='claims'&&<><h2>{t("workbench.claims.sourceCount","{count, number} separately attributed source records","{count, number} einzeln zugeordnete Quellendatensätze",{count:data.sources.length})}</h2><p>{t("workbench.claims.independence","Independent corroboration has not been established. Existing organ membership is retained.","Die unabhängige Bestätigung ist ungeklärt. Bestehende Zuordnungen zur Orgel bleiben erhalten.")}</p><div className="wb-columns">{data.sources.map((x:Row)=><article key={x.source_record_id}><h3>{x.source_key}</h3><a href={x.source_url} target="_blank" rel="noreferrer">{t("workbench.claims.original","Original source","Originalquelle")}</a><p>{x.native_identifier}</p><details><summary>{t("workbench.claims.revision","Source revision and membership","Quellenfassung und Zuordnung")}</summary><Evidence value={x}/></details></article>)}</div><h2>{t("workbench.claims.technical","Reported technical values","Technische Angaben aus den Quellen")}</h2>{data.technicalClaims.length===0&&<p>{t("workbench.claims.noTechnical","No retained aggregate technical assertions for this organ.","Für diese Orgel sind keine zusammengefassten technischen Aussagen erhalten.")}</p>}{data.technicalClaims.map((g:Row)=><article key={g.family}><h3>{workbenchEvidenceLabel(g.family,t)}</h3><p>{g.comparison}</p><div className="wb-table" role="region" tabIndex={0} aria-label={t("workbench.evidence.table","Research evidence table, scroll to see all columns","Belegtabelle. Scrollen Sie zu weiteren Spalten.")}><table><thead><tr><th>{t("workbench.claims.source","Source","Quelle")}</th><th>{t("workbench.claims.value","Reported value","Überlieferte Angabe")}</th><th>{t("workbench.claims.support","Support / conflict","Übereinstimmung oder Widerspruch")}</th><th>{t("workbench.claims.evidence","Evidence","Beleg")}</th></tr></thead><tbody>{g.assertions.map((x:Row)=><tr key={x.fact_id}><td>{x.source_record_id}</td><td>{x.display_value}</td><td>{workbenchEvidenceLabel(x.support_state,t)} · {workbenchEvidenceLabel(x.conflict_state,t)}</td><td><Evidence value={x}/></td></tr>)}</tbody></table></div></article>)}<details><summary>{t("workbench.claims.builders","Builder assertions · {count, number}","Orgelbauerzuschreibungen · {count, number}",{count:data.builderClaims.length})}</summary>{data.builderClaims.map((x:Row)=><article key={x.assertion_id}><strong>{x.source_label}</strong><p>{x.source_record_id} · {x.relation_role} · {x.actor_mdvs_id||t("workbench.claims.identityUnresolved","Identity unresolved","Identität ungeklärt")}</p><Evidence value={x}/></article>)}</details><details><summary>{t("workbench.claims.accounts","Configuration accounts · {count, number}","Dispositionsbeschreibungen · {count, number}",{count:data.accounts.length})}</summary>{data.accounts.map((x:Row)=><article key={x.description_id}><AccountSummary value={x}/></article>)}</details><details><summary>{t("workbench.claims.events","Event assertions · {count, number}","Ereignisaussagen · {count, number}",{count:data.events.length})}</summary>{data.events.map((x:Row)=><Event key={x.event_id} value={x}/>)}</details><a href={url||''} download="modavis-source-comparison.json">{t("workbench.claims.download","Download all attributed claims","Alle zugeordneten Quellenaussagen herunterladen")}</a></>}
 {mode==='terms'&&<><CandidateConcepts concepts={data.candidateConcepts||[]} go={go}/><a href={'/api/workbench/terms/export?'+api} download="modavis-terminology-selection.json">{t("workbench.terms.download","Download complete terminology selection · JSON","Vollständige Terminologieauswahl herunterladen · JSON")}</a><div className="wb-stats"><span>{t("workbench.terms.matchCount","{count, number} matching occurrences","{count, number} passende Vorkommen",{count:data.total})}</span><span>{t("workbench.terms.coverageCount","{count, number} occurrences in selected coverage","{count, number} Vorkommen im gewählten Erfassungsbereich",{count:data.denominator.occurrences})}</span><span>{t("workbench.terms.sourceCount","{count, number} source records","{count, number} Quellendatensätze",{count:data.denominator.sourceRecords})}</span><span>{t("workbench.terms.organCount","{count, number} organs","{count, number} Orgeln",{count:data.denominator.organs})}</span></div><details><summary>{t("workbench.terms.definitions","Controlled vocabulary definitions and retained mappings · {count, number}","Definitionen aus kontrollierten Vokabularen und erhaltene Zuordnungen · {count, number}",{count:data.concepts.length})}</summary>{data.concepts.map((x:Row)=><article key={x.code}><a href={'/vocab/'+enc(x.scheme?.code||'modavis_activity_types')+'/concepts/'+enc(x.code)}><h3>{x.preferredLabel}</h3></a><p>{x.definition}</p><p>{x.labels?.map((l:Row)=>`${l.label} (${l.languageCode||t("workbench.terms.unknownLanguage","unspecified language","Sprache nicht angegeben")})`).join(' · ')}</p>{x.scheme?.code==='modavis_activity_types'&&<button onClick={()=>go({mode:'activities',q:null,concept:x.code,page:0})}>{t("workbench.terms.inspect","Inspect retained occurrences","Erfasste Vorkommen prüfen")}</button>}<Evidence value={x}/></article>)}</details><Pager data={data} go={go} page={Number(params.get('page')||0)}/><div className="wb-table" role="region" tabIndex={0} aria-label={t("workbench.evidence.table","Research evidence table, scroll to see all columns","Belegtabelle. Scrollen Sie zu weiteren Spalten.")}><table><thead><tr><th>{t("workbench.terms.wording","Source wording","Quellenwortlaut")}</th><th>{t("workbench.terms.pitch","Pitch / division","Fußtonlage und Werk")}</th><th>{t("workbench.terms.sourceCountry","Source and country","Quelle und Land")}</th><th>{t("workbench.terms.accountDate","Account date","Datierung der Beschreibung")}</th><th>{t("workbench.terms.mapping","Mapping","Begriffszuordnung")}</th></tr></thead><tbody>{data.items.map((x:Row,i:number)=><tr key={x.id+':'+i}><td><a href={x.href}>{x.label}</a></td><td>{x.pitch||workbenchEvidenceLabel(null,t)} · {x.division||workbenchEvidenceLabel(null,t)}</td><td>{x.source_key} · {x.country||t("workbench.terms.unassigned","Unassigned","Ohne Zuordnung")}</td><td>{x.year??t("workbench.terms.unknownYear","Unestablished","Ungeklärt")} · {workbenchEvidenceLabel(x.date_kind,t)}</td><td>{x.conceptHref?<a href={x.conceptHref}>{x.concept}</a>:x.terminologyMapping?.status==='accepted_lexical_mapping'?<><strong>{t("workbench.terms.candidate","Candidate concept","Begriffskandidat")}</strong><p>{t("workbench.terms.accepted","Accepted lexical mapping","Bestätigte lexikalische Zuordnung")}</p><code>{x.concept}</code></>:t("workbench.terms.unmapped","Unmapped source wording","Quellenwortlaut ohne Begriffszuordnung")}<Evidence value={x}/></td></tr>)}</tbody></table></div></>}
 {mode==='identities'&&<><p>{t("workbench.identities.coverage","The {count, number} groups with competing source identifiers retain their decisions. The Friese generation case is also included. Existing identities and source memberships remain intact.","Für die {count, number} Gruppen mit konkurrierenden Quellenkennungen sind die Entscheidungen dokumentiert. Auch der Fall zu den Generationen der Familie Friese ist enthalten. Bestehende Identitäten und Quellenzuordnungen bleiben erhalten.",{count:data.coverage.competingNativeIdentifiers})}</p>{data.groups.map((g:Row)=><article key={g.nativeId}><h2>{g.sourceNames.join(' / ')} <small>Orgbase {g.nativeId}</small></h2><button onClick={()=>go({view:'occurrences',native:g.nativeId},true)}>{t("workbench.identities.attributions","Inspect individual attributions","Einzelne Zuschreibungen prüfen")}</button><p>{g.finding}</p><p><strong>{t("workbench.identities.established","Established","Belegt")}</strong> {g.resolved}</p><p><strong>{t("workbench.identities.unresolved","Still unresolved","Weiterhin ungeklärt")}</strong> {g.remaining}</p>{g.authorityProfile&&<details><summary>{t("workbench.identities.profile","Inspected authority profile and naming evidence","Geprüfter Normdatensatz und Namensbelege")}</summary><p>{g.authorityProfile.preferredName} · {g.authorityProfile.variantName?.join(' · ')}</p><p>{g.authorityProfile.dateOfBirth?.join('; ')} – {g.authorityProfile.dateOfDeath?.join('; ')}</p><p>{g.authorityProfile.professionOrOccupation?.map((x:Row)=>x.label).join(' · ')}</p><p>{g.authorityProfile.biographicalOrHistoricalInformation?.join('; ')}</p>{g.authorityDateConflicts?.length>0&&<p role="note">{t("workbench.identities.conflict","The retained actor dates and authority dates disagree. Revalidation is required before this authority can anchor a new match.","Die Datierungen im erhaltenen Datensatz und in den Normdaten weichen voneinander ab. Die Normdaten müssen vor einer neuen Zuordnung erneut geprüft werden.")}</p>}<Evidence value={g.authorityDateConflicts}/></details>}<ul>{g.actors.map((a:Row)=><li key={a.mdvs_id}><a href={'/people/'+enc(a.mdvs_id.replace('MDVS:ENTY:',''))}>{a.label}</a> · {a.actor_type}<Evidence value={a}/></li>)}</ul>{g.evidence.map((e:Row,i:number)=><div key={i}><a href={e.url} target="_blank" rel="noreferrer">{e.sourceId}: primary evidence</a>{e.excerpt&&<blockquote>{e.excerpt}</blockquote>}<p className="wb-source">{t("workbench.identities.retrieved","Retrieved {date} · SHA-256 {hash}","Abgerufen am {date} · SHA-256 {hash}",{date:e.retrievedAt,hash:e.sha256})}</p></div>)}</article>)}<a href={url||''} download="modavis-identity-assessments.json">{t("workbench.identities.download","Download identity research","Identitätsrecherche herunterladen")}</a></>}
 </section>}
 <details className="wb-help"><summary>{t("workbench.snapshot.heading","Snapshot and research boundaries","Datenstand und Grenzen der Auswertung")}</summary><p>{t("workbench.snapshot.boundaries","The workbench reads a frozen public core. Its analysis does not alter canonical identities, add sources to organs, or establish physical continuity. Independent corroboration and historical causation require further evidence.","Der Forschungsarbeitsbereich nutzt einen festgelegten öffentlichen Datenstand. Er wahrt die vorhandenen Identitäten und Quellenzuordnungen. Materielle Kontinuität, unabhängige Bestätigung und historische Ursachenzusammenhänge erfordern weitere Belege.")}</p>{context.data&&<p>{t("workbench.snapshot.sha","Core SHA-256","SHA-256 der Kerndaten")} {context.data.publicCoreSha256}</p>}<p>{t("workbench.snapshot.exportLimit","Complete exports support up to {limit, number} records. Narrow larger selections before exporting.","Vollständige Exporte sind für bis zu {limit, number} Datensätze möglich. Grenzen Sie größere Auswahlen vor dem Export ein.",{limit:context.data?.exportLimit??50000})}</p></details>
 </section>;
}
